// Sammelt alle Submission-IDs aus den pending Mails. Ausgabe als CSV-
// String für direkte Verwendung in einer SQL IN-Klausel + als JS-Array
// für nachgelagerte Joins.

const emails = $('Query Pending Emails').first().json.results || [];

function firstLinkedId(link) {
  if (!Array.isArray(link) || link.length === 0) return null;
  const first = link[0];
  if (typeof first === 'string') return first;
  if (first && typeof first === 'object' && first.row_id) return first.row_id;
  return null;
}

const ids = [...new Set(
  emails.map(e => firstLinkedId(e.Submission)).filter(Boolean)
)];

// Empty-Edge-Case: WHERE _id IN ('') ist syntaktisch valid und liefert nichts.
const idsCsv = ids.length > 0
  ? ids.map(id => `'${id}'`).join(',')
  : "''";

return [{ json: { ids, idsCsv } }];

