// Aggregiert alle Send-Ergebnisse zu einem einzigen SeaTable-Batch-Update.
// Erfolg → Status='sent', SentAt=now
// Fehler → Status='failed', ErrorMessage=truncated
// Skip (verwaiste Email) → Status='failed', ErrorMessage='submission_not_found'

const items = $input.all();
const now = new Date();
const pad = n => String(n).padStart(2, '0');
const sentAt = `${now.getUTCFullYear()}-${pad(now.getUTCMonth()+1)}-${pad(now.getUTCDate())} `
            + `${pad(now.getUTCHours())}:${pad(now.getUTCMinutes())}:${pad(now.getUTCSeconds())}`;

const updates = items.map(it => {
  const j = it.json || {};
  const rowId = j.row_id;
  // Skip-Fall (Submission verwaist)
  if (j.skip) {
    return {
      row_id: rowId,
      row: {
        Status: 'failed',
        ErrorMessage: String(j.error || 'unknown_skip').slice(0, 500),
        SentAt: sentAt
      }
    };
  }
  // Fehler-Fall (continueOnFail markiert das Item mit error)
  if (j.error) {
    const msg = typeof j.error === 'string'
      ? j.error
      : (j.error.message || JSON.stringify(j.error));
    return {
      row_id: rowId,
      row: {
        Status: 'failed',
        ErrorMessage: msg.slice(0, 500),
        SentAt: sentAt
      }
    };
  }
  // Erfolgs-Fall (sendMail liefert 202 ohne Body — kein Message-ID-Tracking)
  return {
    row_id: rowId,
    row: {
      Status: 'sent',
      SentAt: sentAt,
      GraphMessageId: ''
    }
  };
}).filter(u => u.row_id);

return [{ json: { table_name: 'ScheduledEmails', updates } }];
